const cleanHtmlContent = (htmlContent) => {
  if (typeof htmlContent !== "string" || !htmlContent) return "";
  let cleaned = htmlContent.replace(/<head[^>]*>[\s\S]*?<\/head>/gi, "");
  cleaned = cleaned.replace(/<\/?(html|body|!DOCTYPE)[^>]*>/gi, "");
  return cleaned;
};


